#!/bin/bash
set -euo pipefail
TAG=$(curl -fsS https://releases.internal/api/shop/current | jq -er '.data.tag')
[[ "$TAG" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || { echo "unexpected tag: $TAG" >&2; exit 1; }
kubectl set image deployment/shop shop=registry.example.com/shop:$TAG -n shop
kubectl rollout status deployment/shop -n shop --timeout=5m
